#!/bin/bash
fail=0
d=$(mktemp -d)
t=$d/bookings.tsv
printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
[ "$(cat "$t")" = "$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty')" ] || { echo "header or other booking changed"; fail=1; }

BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >"$d/out" 2>"$d/err"; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
[ ! -s "$d/out" ] || { echo "not found should print nothing to stdout"; fail=1; }
grep -q '^not found: aoi 2026-01-05 11:00$' "$d/err" || { echo "not found message should go to stderr"; fail=1; }

u=$d/other.tsv
printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$u"
BOOKINGS=$u bash src/cancel.sh kaede 2026-01-05 09:00 >/dev/null || { echo "cancel of kaede failed"; fail=1; }
[ "$(cat "$u")" = "$(printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx')" ] || { echo "cancel removed the wrong room's booking"; fail=1; }

BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >"$d/out" 2>"$d/err"; [ $? = 2 ] || { echo "usage error should exit 2"; fail=1; }
[ ! -s "$d/out" ] || { echo "usage error should print nothing to stdout"; fail=1; }
grep -q '^usage: cancel.sh ROOM DATE START$' "$d/err" || { echo "usage message should go to stderr"; fail=1; }
rm -rf "$d"; exit $fail

